                  >
                    <el-input-number 
                      v-model="maintenanceSettings.backupRetentionDays" 
                      :min="1" 
                      :max="365"
                      controls-position="right"
                    />
                    <div class="field-description">备份文件的保留时间（1-365天）</div>
                  </el-form-item>
                </div>
                
                <div class="form-group">
                  <el-form-item label="自动清理日志">
