        background: transparent;
        transition: all 0.3s ease;
        white-space: nowrap;
        margin-right: 4px;
        
        &:last-child {
          margin-right: 0;
        }
        
        &.is-active {
          background: linear-gradient(135deg, #374151 0%, #111827 100%);
          color: #ffffff;
          box-shadow: 0 2px 8px rgba(55, 65, 81, 0.3);
        }
        
        &:hover {
          background: #f3f4f6;
          color: #374151;
        }
      }
      
      .tab-label {
        display: flex;
        flex-direction: column;
        align-items: center;
        gap: 4px;
        min-height: 40px;
        justify-content: center;
        
        .el-icon {
          font-size: 16px;
          flex-shrink: 0;
        }
        
        span {
          font-size: 11px;
          line-height: 1.2;
          text-align: center;
          white-space: nowrap;
          overflow: hidden;
          text-overflow: ellipsis;
          max-width: 100%;
        }
      }
      
      // 滑动条指示器样式
      .scroll-indicator {
        margin-top: 12px;
        padding: 0 8px;
        display: block !important;
        visibility: visible !important;
        opacity: 1 !important;
        
        .scroll-track {
          width: 100%;
          height: 8px;
          background: #e5e7eb;
          border-radius: 4px;
          position: relative;
          overflow: hidden;
          box-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.1);
          border: 1px solid #d1d5db;
          
          .scroll-thumb {
            height: 100%;
            background: linear-gradient(90deg, #374151 0%, #111827 100%);
            border-radius: 4px;
            transition: all 0.3s ease;
            position: absolute;
            top: 0;
            left: 0;
            min-width: 40px;
            box-shadow: 0 2px 4px rgba(55, 65, 81, 0.4);
            border: 1px solid rgba(255, 255, 255, 0.3);
            
            &::after {
              content: '';
              position: absolute;
              top: 50%;
              left: 50%;
              transform: translate(-50%, -50%);
              width: 24px;
              height: 2px;
              background: rgba(255, 255, 255, 0.9);
              border-radius: 1px;
            }
          }
        }
      }
    }
